INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e CROSS JOIN (VALUES (0, $batch04$Given that$batch04$, $batch04$Horses thrive in grasslands.$batch04$), (1, $batch04$How can it be that$batch04$, $batch04$The horse population peaked during a cold period 25,000 years ago, then dropped quickly once the climate warmed?$batch04$), (2, $batch04$Evaluate$batch04$, $batch04$Horses depend on grassland, so the climate has to be changing how much grassland there is. We tend to assume grass grows better in warmth, but the stimulus never says that. If grassland spreads in the cold and shrinks in the warmth, the timing fits.$batch04$), (3, $batch04$Goal$batch04$, $batch04$Find a link between cold periods and more grassland, and between warming and less.$batch04$)) v(position,label,body) WHERE e.id=$batch04$476df4b7-33a6-4c7e-9ac8-0612d33f4160$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
